SELECT id, customer_id, status, AVG(monthly_fee) OVER (PARTITION BY status, plan ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_3_prior, SUM(monthly_fee) OVER (ORDER BY end_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, FIRST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY plan ORDER BY end_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee, FIRST_VALUE(monthly_fee) IGNORE NULLS OVER w_ordered AS first_known_monthly_fee_2 FROM subscriptions WHERE start_date BETWEEN '2024-04-24' AND '2025-05-01' WINDOW w_ordered AS (PARTITION BY customer_id ORDER BY monthly_fee ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
